template <typename T>
struct default_traits {
    static constexpr bool is_pod = false;
    using underlying_type = T;
};

// Specialization for fundamental type (e.g., int)
template <>
struct default_traits<int> {
    static constexpr bool is_pod = true;
    using underlying_type = int;
};

// Partial Specialization (C array types)
template <typename T, size_t N>
struct default_traits<T[N]> {
    static constexpr bool is_pod = default_traits<T>::is_pod;
    using underlying_type = T;
};

// Compile-time checks
constexpr bool check_a = default_traits<int>::is_pod;     // true
constexpr bool check_b = default_traits<std::string>::is_pod; // false
using ArrayT = default_traits<int[10]>::underlying_type; // int
